def set_zeroes(matrix):
    if not matrix: return
    n, m = len(matrix), len(matrix[0])
    first_row_zero = any(matrix[0][j] == 0 for j in range(m))
    first_col_zero = any(matrix[i][0] == 0 for i in range(n))

    # Use first row/col for marking
    for i in range(1, n):
        for j in range(1, m):
            if matrix[i][j] == 0:
                matrix[0][j] = 0
                matrix[i][0] = 0

    # Set zeros
    for i in range(1, n):
        for j in range(1, m):
            if matrix[0][j] == 0 or matrix[i][0] == 0:
                matrix[i][j] = 0

    # Handle first row/col
    if first_row_zero:
        for j in range(m): matrix[0][j] = 0
    if first_col_zero:
        for i in range(n): matrix[i][0] = 0

