def quick_sort(arr):
    def _sort(low, high):
        if low < high:
            pi = partition(low, high)
            _sort(low, pi-1)
            _sort(pi+1, high)

    def partition(low, high):
        pivot = arr[high]
        i = low - 1
        for j in range(low, high):
            if arr[j] < pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i+1], arr[high] = arr[high], arr[i+1]
        return i+1

    _sort(0, len(arr)-1)

